#include <Arduino.h>
#include <string.h>
#include <WiFi.h>
#include <esp_now.h>

constexpr uint8_t PEER_COUNT = 2;
const uint8_t peerMacs[PEER_COUNT][6] = {
  {0x24, 0x6F, 0x28, 0xAA, 0xBB, 0x01},
  {0x24, 0x6F, 0x28, 0xAA, 0xBB, 0x02},
};

struct SamplePacket {
  uint8_t nodeId;
  uint32_t sequence;
  int16_t temperatureCentiC;
};

SamplePacket packet{1, 0, 2150};

void encodePacket(uint8_t* frame) {
  frame[0] = packet.nodeId;
  frame[1] = static_cast<uint8_t>(packet.sequence >> 24);
  frame[2] = static_cast<uint8_t>(packet.sequence >> 16);
  frame[3] = static_cast<uint8_t>(packet.sequence >> 8);
  frame[4] = static_cast<uint8_t>(packet.sequence);
  const uint16_t temperature =
      static_cast<uint16_t>(packet.temperatureCentiC);
  frame[5] = static_cast<uint8_t>(temperature >> 8);
  frame[6] = static_cast<uint8_t>(temperature);
}

void setup() {
  Serial.begin(115200);
  if (!WiFi.mode(WIFI_STA)) {
    Serial.println("Wi-Fi station mode failed");
    return;
  }
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW initialization failed");
    return;
  }

  for (uint8_t i = 0; i < PEER_COUNT; ++i) {
    esp_now_peer_info_t peer{};
    memcpy(peer.peer_addr, peerMacs[i], 6);
    peer.channel = 0;
    peer.ifidx = WIFI_IF_STA;
    peer.encrypt = false;
    if (esp_now_add_peer(&peer) != ESP_OK) {
      Serial.printf("peer %u could not be added\n", static_cast<unsigned>(i));
    }
  }
}

void loop() {
  ++packet.sequence;
  uint8_t frame[7];
  encodePacket(frame);
  for (uint8_t i = 0; i < PEER_COUNT; ++i) {
    if (esp_now_send(peerMacs[i],
                     frame,
                     sizeof(frame)) != ESP_OK) {
      Serial.printf("send to peer %u failed\n", static_cast<unsigned>(i));
    }
  }
  delay(1000);
}
